import React, { createContext, useContext, useState } from "react";
import axiosClient from "../api/axiosClient";

const AuthContext = createContext(null);

function persistSession(data) {
  localStorage.setItem("aquatrack_token", data.token);
  localStorage.setItem("aquatrack_user", JSON.stringify(data));
}

export function AuthProvider({ children }) {
  const [user, setUser] = useState(() => {
    const stored = localStorage.getItem("aquatrack_user");
    return stored ? JSON.parse(stored) : null;
  });

  const login = async (username, password) => {
    const res = await axiosClient.post("/auth/login", { username, password });
    const data = res.data;
    persistSession(data);
    setUser(data);
    return data;
  };

  /**
   * Adaptive Registration method:
   * Accepts either an explicit payload object OR individual positional arguments
   * (username, email, password, apartmentId, flatNumber, fullName).
   */
  const register = async (param1, email, password, apartmentId, flatNumber, fullName) => {
    let payload = {};

    if (typeof param1 === "object" && param1 !== null) {
      // Called as: register({ username, email, ... })
      payload = param1;
    } else {
      // Called with positional args: register(username, email, password, apartmentId, flatNumber, fullName)
      const username = param1;

      // 1. Fetch households for the selected apartment to resolve householdId from flatNumber
      let householdId = null;
      try {
        const hRes = await axiosClient.get(`/public/apartments/${apartmentId}/households`);
        const matchingFlat = hRes.data.find(
          (h) => String(h.flatNumber).trim().toLowerCase() === String(flatNumber).trim().toLowerCase()
        );
        if (matchingFlat) {
          householdId = matchingFlat.id;
        } else {
          throw new Error(`Flat "${flatNumber}" was not found under the selected apartment.`);
        }
      } catch (err) {
        throw new Error(err.message || "Failed to find household unit details.");
      }

      payload = {
        username: username,
        email: email,
        password: password,
        fullName: fullName || username,
        role: "RESIDENT",
        apartmentId: Number(apartmentId),
        householdId: householdId,
      };
    }

    const res = await axiosClient.post("/auth/register", payload);
    const data = res.data;

    // Note: Pending resident accounts won't have an active token until approved by admin
    if (data && data.token) {
      persistSession(data);
      setUser(data);
    }
    return data;
  };

  /**
   * Sends the Google ID token (from Google Identity Services) to the backend.
   * If a matching resident account exists, logs in and returns { accountExists: true }.
   * Otherwise returns { accountExists: false, googleEmail, googleFullName } so the
   * caller can collect apartment + flat number and call googleRegister().
   */
  const googleLogin = async (idToken) => {
    const res = await axiosClient.post("/auth/google/login", { idToken });
    const data = res.data;
    if (data.accountExists) {
      persistSession(data.auth);
      setUser(data.auth);
    }
    return data;
  };

  const googleRegister = async (idToken, apartmentId, flatNumber) => {
    const res = await axiosClient.post("/auth/google/register", { idToken, apartmentId, flatNumber });
    const data = res.data;
    if (data && data.token) {
      persistSession(data);
      setUser(data);
    }
    return data;
  };

  const logout = () => {
    localStorage.removeItem("aquatrack_token");
    localStorage.removeItem("aquatrack_user");
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, login, register, googleLogin, googleRegister, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  return useContext(AuthContext);
}
